{
  "title": "太空求生：救援信号",
  "scene": "飞船的主控室被厚重的尘埃覆盖，但一道微弱的橙色光芒在远处闪烁。你站在控制台前，可以看到舱壁上的小屏幕显示着一个遥远星球的轮廓。这时，另一个屏幕突然显示出了一个紧急信号，上面写着：“请前往坐标（1234, 5678），有重要物品等待收集。任务成功后，返回这里等待进一步指示。”",
  "goal": "根据信号前往指定坐标，找到重要物品并返回基地。",
  "choices": [
    {
      "id": "A",
      "text": "直接前往坐标（1234, 5678）",
      "outcome": "快速启程，但进入大气层时飞船遭遇了一股强大的电磁干扰，导致导航系统受损，幸亏你记得关闭了不必要的设备以节省能源，勉强抵达了坐标位置。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "先检查飞船系统，确保无误后再前往",
      "outcome": "仔细检查后发现了一个关键的电源模块松动，修复后重新启程，但消耗了大量的补给时间。抵达坐标时，发现目标物品已被其它的太空海盗先一步占据。",
      "result": "fail",
      "next": "bad_end"
    },
    {
      "id": "C",
      "text": "先联系基地请求支援",
      "outcome": "通过无线电联系基地，请求紧急支援。等待了一段时间后，基地派来了携带维修工具的飞船。你们一起前往目标坐标，顺利找到了物品，并安全返回基地。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
